model Ball {
  id: ID
  x: Number
  y: Number
  vx: Number
  vy: Number
  radius: Number
}

component BallSimulation {
  state balls: Ball[] = []
  state frames = 0
  state paused = false
  ref canvas
  ref animationId

  fn initBalls {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push({
        id: crypto.randomUUID(),
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: (Math.random() - 0.5) * 8,
        vy: (Math.random() - 0.5) * 8,
        radius: 10
      })
    }
    frames = 0
  }

  fn addBall {
    balls.push({
      id: crypto.randomUUID(),
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 8,
      radius: 10
    })
  }

  fn togglePause {
    paused = !paused
  }

  fn updatePhysics {
    const gravity = 0.2
    const width = 400
    const height = 300

    for (let i = 0; i < balls.length; i++) {
      const b = balls[i]
      b.vy += gravity
      b.x += b.vx
      b.y += b.vy

      if (b.x - b.radius < 0) {
        b.x = b.radius
        b.vx = -b.vx
      }
      if (b.x + b.radius > width) {
        b.x = width - b.radius
        b.vx = -b.vx
      }
      if (b.y - b.radius < 0) {
        b.y = b.radius
        b.vy = -b.vy
      }
      if (b.y + b.radius > height) {
        b.y = height - b.radius
        b.vy = -b.vy
      }
    }

    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const b1 = balls[i]
        const b2 = balls[j]
        const dx = b2.x - b1.x
        const dy = b2.y - b1.y
        const dist = Math.sqrt(dx * dx + dy * dy)

        if (dist < b1.radius + b2.radius) {
          const tempVx = b1.vx
          const tempVy = b1.vy
          b1.vx = b2.vx
          b1.vy = b2.vy
          b2.vx = tempVx
          b2.vy = tempVy
        }
      }
    }
  }

  fn draw {
    const ctx = canvas.getContext("2d")
    ctx.fillStyle = "#fff"
    ctx.fillRect(0, 0, 400, 300)
    ctx.strokeStyle = "#000"
    ctx.lineWidth = 1
    ctx.strokeRect(0, 0, 400, 300)

    ctx.fillStyle = "#e11d48"
    for (const b of balls) {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn animate {
    if (!paused) {
      updatePhysics()
      frames++
    }
    draw()
    animationId = requestAnimationFrame(animate)
  }

  mount {
    initBalls()
    draw()
    animationId = requestAnimationFrame(animate)
    cleanup {
      cancelAnimationFrame(animationId)
    }
  }

  column gap=4 {
    row gap=2 {
      button "Agregar" -> addBall()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" -> initBalls()
    }
    row gap=4 {
      text `Pelotas: ${balls.length}`
      text `Cuadros: ${frames}`
    }
    canvas id="sim" ref=canvas width=400 height=300 style="border: 1px solid #000; background: white;"
  }
}

