import React, { useEffect, useRef, useState } from 'react';

interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [balls, setBalls] = useState<Ball[]>([]);
  const [isPaused, setIsPaused] = useState(false);
  const [frameCount, setFrameCount] = useState(0);
  const animationRef = useRef<number | null>(null);
  const ballsRef = useRef<Ball[]>([]);
  const frameCountRef = useRef(0);
  const isPausedRef = useRef(false);

  const CANVAS_WIDTH = 400;
  const CANVAS_HEIGHT = 300;
  const BALL_RADIUS = 10;
  const GRAVITY = 0.2;

  const createBall = (): Ball => ({
    x: Math.random() * (CANVAS_WIDTH - 2 * BALL_RADIUS) + BALL_RADIUS,
    y: Math.random() * (CANVAS_HEIGHT - 2 * BALL_RADIUS) + BALL_RADIUS,
    vx: (Math.random() - 0.5) * 8,
    vy: (Math.random() - 0.5) * 8,
    radius: BALL_RADIUS,
  });

  const initializeBalls = () => {
    const initialBalls = Array.from({ length: 5 }, createBall);
    ballsRef.current = initialBalls;
    setBalls(initialBalls);
    frameCountRef.current = 0;
    setFrameCount(0);
  };

  useEffect(() => {
    initializeBalls();
  }, []);

  const checkCollision = (ball1: Ball, ball2: Ball): boolean => {
    const dx = ball2.x - ball1.x;
    const dy = ball2.y - ball1.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    return distance < ball1.radius + ball2.radius;
  };

  const handleCollision = (ball1: Ball, ball2: Ball) => {
    const temp = ball1.vx;
    ball1.vx = ball2.vx;
    ball2.vx = temp;

    const temp2 = ball1.vy;
    ball1.vy = ball2.vy;
    ball2.vy = temp2;
  };

  const updateBalls = () => {
    if (isPausedRef.current) return;

    const ballsToUpdate = ballsRef.current;

    for (let i = 0; i < ballsToUpdate.length; i++) {
      const ball = ballsToUpdate[i];

      ball.vy += GRAVITY;

      ball.x += ball.vx;
      ball.y += ball.vy;

      if (ball.x - ball.radius < 0) {
        ball.x = ball.radius;
        ball.vx = Math.abs(ball.vx);
      }
      if (ball.x + ball.radius > CANVAS_WIDTH) {
        ball.x = CANVAS_WIDTH - ball.radius;
        ball.vx = -Math.abs(ball.vx);
      }
      if (ball.y - ball.radius < 0) {
        ball.y = ball.radius;
        ball.vy = Math.abs(ball.vy);
      }
      if (ball.y + ball.radius > CANVAS_HEIGHT) {
        ball.y = CANVAS_HEIGHT - ball.radius;
        ball.vy = -Math.abs(ball.vy);
      }
    }

    for (let i = 0; i < ballsToUpdate.length; i++) {
      for (let j = i + 1; j < ballsToUpdate.length; j++) {
        if (checkCollision(ballsToUpdate[i], ballsToUpdate[j])) {
          handleCollision(ballsToUpdate[i], ballsToUpdate[j]);
        }
      }
    }

    frameCountRef.current++;
    setFrameCount(frameCountRef.current);
  };

  const drawBalls = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const ballsToRender = ballsRef.current;
    for (const ball of ballsToRender) {
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx.fillStyle = '#3b82f6';
      ctx.fill();
      ctx.strokeStyle = '#1e40af';
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  };

  useEffect(() => {
    const animate = () => {
      updateBalls();
      drawBalls();
      animationRef.current = requestAnimationFrame(animate);
    };

    animationRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationRef.current !== null) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  const handleAddBall = () => {
    const newBall = createBall();
    ballsRef.current.push(newBall);
    setBalls([...ballsRef.current]);
  };

  const handlePauseResume = () => {
    isPausedRef.current = !isPausedRef.current;
    setIsPaused(!isPaused);
  };

  const handleRestart = () => {
    initializeBalls();
    isPausedRef.current = false;
    setIsPaused(false);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-900 p-4">
      <div className="bg-gray-800 rounded-lg shadow-lg p-6">
        <h1 className="text-3xl font-bold text-white mb-4 text-center">
          Simulación de Pelotas
        </h1>

        <canvas
          ref={canvasRef}
          id="sim"
          width={CANVAS_WIDTH}
          height={CANVAS_HEIGHT}
          className="border-4 border-blue-500 bg-white mb-4 block mx-auto rounded"
        />

        <div className="text-white text-center mb-4 space-y-2">
          <p className="text-lg font-semibold">Pelotas: {ballsRef.current.length}</p>
          <p className="text-lg font-semibold">Cuadros: {frameCount}</p>
        </div>

        <div className="flex gap-3 justify-center flex-wrap">
          <button
            onClick={handleAddBall}
            className="px-6 py-2 bg-green-500 hover:bg-green-600 text-white font-bold rounded transition"
          >
            Agregar
          </button>
          <button
            onClick={handlePauseResume}
            className="px-6 py-2 bg-yellow-500 hover:bg-yellow-600 text-white font-bold rounded transition"
          >
            {isPaused ? 'Reanudar' : 'Pausar'}
          </button>
          <button
            onClick={handleRestart}
            className="px-6 py-2 bg-red-500 hover:bg-red-600 text-white font-bold rounded transition"
          >
            Reiniciar
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useRef, useState } from 'react';

interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [balls, setBalls] = useState<Ball[]>([]);
  const [isRunning, setIsRunning] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const animationRef = useRef<number | null>(null);
  const ballsRef = useRef<Ball[]>([]);
  const frameCountRef = useRef(0);
  const isRunningRef = useRef(true);

  const CANVAS_WIDTH = 400;
  const CANVAS_HEIGHT = 300;
  const BALL_RADIUS = 10;
  const GRAVITY = 0.2;

  const createBall = (): Ball => ({
    x: Math.random() * (CANVAS_WIDTH - 2 * BALL_RADIUS) + BALL_RADIUS,
    y: Math.random() * (CANVAS_HEIGHT - 2 * BALL_RADIUS) + BALL_RADIUS,
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6,
    radius: BALL_RADIUS,
    color: `hsl(${Math.random() * 360}, 100%, 50%)`,
  });

  const initializeBalls = () => {
    const newBalls = Array.from({ length: 5 }, () => createBall());
    ballsRef.current = newBalls;
    setBalls(newBalls);
    frameCountRef.current = 0;
    setFrameCount(0);
  };

  useEffect(() => {
    initializeBalls();
  }, []);

  const updateBalls = () => {
    const balls = ballsRef.current;

    // Apply gravity
    balls.forEach((ball) => {
      ball.vy += GRAVITY;
    });

    // Update positions
    balls.forEach((ball) => {
      ball.x += ball.vx;
      ball.y += ball.vy;
    });

    // Handle wall collisions
    balls.forEach((ball) => {
      if (ball.x - ball.radius < 0) {
        ball.x = ball.radius;
        ball.vx = -ball.vx * 0.99;
      }
      if (ball.x + ball.radius > CANVAS_WIDTH) {
        ball.x = CANVAS_WIDTH - ball.radius;
        ball.vx = -ball.vx * 0.99;
      }
      if (ball.y - ball.radius < 0) {
        ball.y = ball.radius;
        ball.vy = -ball.vy * 0.99;
      }
      if (ball.y + ball.radius > CANVAS_HEIGHT) {
        ball.y = CANVAS_HEIGHT - ball.radius;
        ball.vy = -ball.vy * 0.99;
      }
    });

    // Handle ball collisions
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const ball1 = balls[i];
        const ball2 = balls[j];

        const dx = ball2.x - ball1.x;
        const dy = ball2.y - ball1.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < ball1.radius + ball2.radius) {
          // Elastic collision - exchange velocities
          const tempVx = ball1.vx;
          const tempVy = ball1.vy;
          ball1.vx = ball2.vx;
          ball1.vy = ball2.vy;
          ball2.vx = tempVx;
          ball2.vy = tempVy;

          // Separate balls to prevent overlap
          const overlap = ball1.radius + ball2.radius - distance;
          const angle = Math.atan2(dy, dx);
          const moveX = (overlap / 2) * Math.cos(angle);
          const moveY = (overlap / 2) * Math.sin(angle);

          ball1.x -= moveX;
          ball1.y -= moveY;
          ball2.x += moveX;
          ball2.y += moveY;
        }
      }
    }
  };

  const drawBalls = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ballsRef.current.forEach((ball) => {
      ctx.fillStyle = ball.color;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1;
      ctx.stroke();
    });
  };

  const animate = () => {
    if (isRunningRef.current) {
      updateBalls();
      drawBalls();

      frameCountRef.current += 1;
      setFrameCount(frameCountRef.current);
      setBalls([...ballsRef.current]);
    }

    animationRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    animationRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  useEffect(() => {
    isRunningRef.current = isRunning;
  }, [isRunning]);

  const handleAddBall = () => {
    const newBall = createBall();
    ballsRef.current = [...ballsRef.current, newBall];
    setBalls([...ballsRef.current]);
  };

  const handleTogglePause = () => {
    setIsRunning(!isRunning);
  };

  const handleRestart = () => {
    initializeBalls();
    setIsRunning(true);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
      <div className="bg-white rounded-lg shadow-lg p-8">
        <h1 className="text-3xl font-bold text-gray-800 mb-6 text-center">
          Simulación de Pelotas
        </h1>

        <canvas
          ref={canvasRef}
          width={CANVAS_WIDTH}
          height={CANVAS_HEIGHT}
          id="sim"
          className="border-4 border-indigo-500 rounded-lg mb-6 bg-white shadow-md"
        />

        <div className="flex gap-4 justify-center mb-6">
          <button
            onClick={handleAddBall}
            className="px-6 py-2 bg-green-500 hover:bg-green-600 text-white font-semibold rounded-lg transition-colors duration-200 shadow-md"
          >
            Agregar
          </button>

          <button
            onClick={handleTogglePause}
            className="px-6 py-2 bg-yellow-500 hover:bg-yellow-600 text-white font-semibold rounded-lg transition-colors duration-200 shadow-md"
          >
            {isRunning ? 'Pausar' : 'Reanudar'}
          </button>

          <button
            onClick={handleRestart}
