import { createSignal, createEffect, onCleanup } from 'solid-js';

interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
}

export default function BallSimulation() {
  const CANVAS_WIDTH = 400;
  const CANVAS_HEIGHT = 300;
  const GRAVITY = 0.2;
  const INITIAL_BALL_COUNT = 5;
  const BALL_RADIUS = 10;

  let canvas: HTMLCanvasElement | undefined;
  let ctx: CanvasRenderingContext2D | null = null;
  let animationId: number | null = null;

  const [balls, setBalls] = createSignal<Ball[]>([]);
  const [frameCount, setFrameCount] = createSignal(0);
  const [isPaused, setIsPaused] = createSignal(false);
  const [pauseButtonText, setPauseButtonText] = createSignal('Pausar');

  const createRandomBall = (): Ball => {
    return {
      x: Math.random() * (CANVAS_WIDTH - 2 * BALL_RADIUS) + BALL_RADIUS,
      y: Math.random() * (CANVAS_HEIGHT - 2 * BALL_RADIUS) + BALL_RADIUS,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 8,
      radius: BALL_RADIUS,
    };
  };

  const initializeBalls = () => {
    const newBalls: Ball[] = [];
    for (let i = 0; i < INITIAL_BALL_COUNT; i++) {
      newBalls.push(createRandomBall());
    }
    setBalls(newBalls);
    setFrameCount(0);
  };

  const addBall = () => {
    setBalls([...balls(), createRandomBall()]);
  };

  const togglePause = () => {
    setIsPaused(!isPaused());
    setPauseButtonText(isPaused() ? 'Pausar' : 'Reanudar');
  };

  const reinitialize = () => {
    setIsPaused(false);
    setPauseButtonText('Pausar');
    initializeBalls();
  };

  const updatePhysics = () => {
    const currentBalls = balls();

    // Apply gravity
    currentBalls.forEach((ball) => {
      ball.vy += GRAVITY;
    });

    // Update positions
    currentBalls.forEach((ball) => {
      ball.x += ball.vx;
      ball.y += ball.vy;
    });

    // Bounce off walls
    currentBalls.forEach((ball) => {
      if (ball.x - ball.radius < 0) {
        ball.x = ball.radius;
        ball.vx = -ball.vx;
      }
      if (ball.x + ball.radius > CANVAS_WIDTH) {
        ball.x = CANVAS_WIDTH - ball.radius;
        ball.vx = -ball.vx;
      }
      if (ball.y - ball.radius < 0) {
        ball.y = ball.radius;
        ball.vy = -ball.vy;
      }
      if (ball.y + ball.radius > CANVAS_HEIGHT) {
        ball.y = CANVAS_HEIGHT - ball.radius;
        ball.vy = -ball.vy;
      }
    });

    // Check collisions between balls
    for (let i = 0; i < currentBalls.length; i++) {
      for (let j = i + 1; j < currentBalls.length; j++) {
        const ball1 = currentBalls[i];
        const ball2 = currentBalls[j];

        const dx = ball2.x - ball1.x;
        const dy = ball2.y - ball1.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < ball1.radius + ball2.radius) {
          // Elastic collision - exchange velocities
          const tempVx = ball1.vx;
          const tempVy = ball1.vy;
          ball1.vx = ball2.vx;
          ball1.vy = ball2.vy;
          ball2.vx = tempVx;
          ball2.vy = tempVy;

          // Separate balls to prevent overlap
          const overlap = ball1.radius + ball2.radius - distance;
          const angle = Math.atan2(dy, dx);
          const moveX = (overlap / 2) * Math.cos(angle);
          const moveY = (overlap / 2) * Math.sin(angle);

          ball1.x -= moveX;
          ball1.y -= moveY;
          ball2.x += moveX;
          ball2.y += moveY;
        }
      }
    }

    setBalls([...currentBalls]);
  };

  const draw = () => {
    if (!ctx) return;

    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.strokeRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const currentBalls = balls();
    currentBalls.forEach((ball, index) => {
      ctx!.fillStyle = `hsl(${(index * 360) / currentBalls.length}, 70%, 60%)`;
      ctx!.beginPath();
      ctx!.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx!.fill();
    });
  };

  const animate = () => {
    if (!isPaused()) {
      updatePhysics();
      setFrameCount(frameCount() + 1);
    }
    draw();
    animationId = requestAnimationFrame(animate);
  };

  createEffect(() => {
    if (canvas) {
      ctx = canvas.getContext('2d');
      initializeBalls();
      animationId = requestAnimationFrame(animate);
    }

    onCleanup(() => {
      if (animationId !== null) {
        cancelAnimationFrame(animationId);
      }
    });
  });

  return (
    <div class="flex flex-col items-center gap-6 p-8 bg-gray-800 rounded-lg shadow-2xl">
      <h1 class="text-3xl font-bold text-white">Simulación de Pelotas</h1>

      <canvas
        ref={canvas}
        id="sim"
        width={CANVAS_WIDTH}
        height={CANVAS_HEIGHT}
        class="border-4 border-gray-600 bg-gray-950 rounded"
      />

      <div class="flex gap-4">
        <button
          onclick={addBall}
          class="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded transition-colors"
        >
          Agregar
        </button>
        <button
          onclick={togglePause}
          class="px-6 py-2 bg-yellow-600 hover:bg-yellow-700 text-white font-semibold rounded transition-colors"
        >
          {pauseButtonText()}
        </button>
        <button
          onclick={reinitialize}
          class="px-6 py-2 bg-red-600 hover:bg-red-700 text-white font-semibold rounded transition-colors"
        >
          Reiniciar
        </button>
      </div>

      <div class="text-white text-lg font-semibold">
        <p>Pelotas: {balls().length}</p>
        <p>Cuadros: {frameCount()}</p>
      </div>
    </div>
  );
}

