import { createSignal, createEffect, onCleanup } from 'solid-js';

interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
}

export default function BallSimulation() {
  const canvasWidth = 400;
  const canvasHeight = 300;
  const ballRadius = 10;
  const gravity = 0.2;

  let canvasRef: HTMLCanvasElement | undefined;
  let animationId: number | null = null;

  const [balls, setBalls] = createSignal<Ball[]>([]);
  const [frames, setFrames] = createSignal(0);
  const [isPaused, setIsPaused] = createSignal(false);

  const createRandomBall = (): Ball => ({
    x: Math.random() * (canvasWidth - ballRadius * 2) + ballRadius,
    y: Math.random() * (canvasHeight - ballRadius * 2) + ballRadius,
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6,
    radius: ballRadius,
  });

  const initializeBalls = () => {
    const newBalls = Array.from({ length: 5 }, () => createRandomBall());
    setBalls(newBalls);
    setFrames(0);
  };

  const addBall = () => {
    setBalls([...balls(), createRandomBall()]);
  };

  const checkCollision = (ball1: Ball, ball2: Ball): boolean => {
    const dx = ball2.x - ball1.x;
    const dy = ball2.y - ball1.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    return distance < ball1.radius + ball2.radius;
  };

  const handleCollision = (ball1: Ball, ball2: Ball) => {
    const temp = ball1.vx;
    ball1.vx = ball2.vx;
    ball2.vx = temp;

    const temp2 = ball1.vy;
    ball1.vy = ball2.vy;
    ball2.vy = temp2;
  };

  const updateBalls = () => {
    const currentBalls = balls();

    currentBalls.forEach((ball) => {
      ball.vy += gravity;
      ball.x += ball.vx;
      ball.y += ball.vy;

      if (ball.x - ball.radius <= 0) {
        ball.x = ball.radius;
        ball.vx = Math.abs(ball.vx);
      }
      if (ball.x + ball.radius >= canvasWidth) {
        ball.x = canvasWidth - ball.radius;
        ball.vx = -Math.abs(ball.vx);
      }

      if (ball.y - ball.radius <= 0) {
        ball.y = ball.radius;
        ball.vy = Math.abs(ball.vy);
      }
      if (ball.y + ball.radius >= canvasHeight) {
        ball.y = canvasHeight - ball.radius;
        ball.vy = -Math.abs(ball.vy);
      }
    });

    for (let i = 0; i < currentBalls.length; i++) {
      for (let j = i + 1; j < currentBalls.length; j++) {
        if (checkCollision(currentBalls[i], currentBalls[j])) {
          handleCollision(currentBalls[i], currentBalls[j]);
        }
      }
    }
  };

  const drawBalls = () => {
    if (!canvasRef) return;

    const ctx = canvasRef.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);

    ctx.strokeStyle = '#9ca3af';
    ctx.lineWidth = 1;
    ctx.strokeRect(0, 0, canvasWidth, canvasHeight);

    balls().forEach((ball) => {
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = '#1e40af';
      ctx.lineWidth = 2;
      ctx.stroke();
    });
  };

  const animate = () => {
    if (!isPaused()) {
      updateBalls();
      setFrames((f) => f + 1);
    }

    drawBalls();
    animationId = requestAnimationFrame(animate);
  };

  createEffect(() => {
    initializeBalls();

    animationId = requestAnimationFrame(animate);

    onCleanup(() => {
      if (animationId !== null) {
        cancelAnimationFrame(animationId);
      }
    });
  });

  return (
    <div class="flex flex-col items-center gap-4">
      <canvas
        ref={canvasRef}
        width={canvasWidth}
        height={canvasHeight}
        id="sim"
        class="border-2 border-gray-300 bg-gray-800"
      />

      <div class="flex gap-4">
        <button
          onClick={addBall}
          class="px-4 py-2 bg-green-600 hover:bg-green-700 text-white font-semibold rounded transition"
        >
          Agregar
        </button>

        <button
          onClick={() => setIsPaused(!isPaused())}
          class="px-4 py-2 bg-yellow-600 hover:bg-yellow-700 text-white font-semibold rounded transition"
        >
          {isPaused() ? 'Reanudar' : 'Pausar'}
        </button>

        <button
          onClick={initializeBalls}
          class="px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-semibold rounded transition"
        >
          Reiniciar
        </button>
      </div>

      <div class="text-white text-lg font-semibold">
        <p>Pelotas: {balls().length}</p>
        <p>Cuadros: {frames()}</p>
      </div>
    </div>
  );
}
